Bash {"command":"cd "D:/code/tutors/test-course-python" && node -e "
const topics = require('./topics-1-3.js');

const baseFields = ['route','type','title','summary','contentMd','frontMatter','id','img','imgFile','video','videoids','hide','authLevel'];
let errors = [];

function checkBase(obj, path) {
  baseFields.forEach(f => {
    if (!(f in obj)) errors.push(path + ' missing field: ' + f);
  });
  if (!('videoid' in (obj.videoids || {}))) errors.push(path + ' videoids missing videoid');
  if (!('videoIds' in (obj.videoids || {}))) errors.push(path + ' videoids missing videoIds');
}

function checkLO(obj, path) {
  checkBase(obj, path);

  if (obj.type === 'topic' || obj.type === 'unit') {
    if (!Array.isArray(obj.los)) errors.push(path + ' missing los array');
    else obj.los.forEach((c, i) => checkLO(c, path + '/los[' + i + ']'));
  }

  if (obj.type === 'talk') {
    if (!('pdf' in obj)) errors.push(path + ' talk missing pdf');
    if (!('pdfFile' in obj)) errors.push(path + ' talk missing pdfFile');
    if (obj.frontMatter.marp !== 'true') errors.push(path + ' talk frontMatter.marp should be \"true\"');
  }

  if (obj.type === 'notebook') {
    if (!Array.isArray(obj.cells)) errors.push(path + ' notebook missing cells');
    if (obj.kernelLanguage !== 'python') errors.push(path + ' notebook kernelLanguage not python');
    if (obj.cells) {
      obj.cells.forEach((cell, ci) => {
        const cp = path + '/cells[' + ci + ']';
        if (!cell.cellType) errors.push(cp + ' missing cellType');
        if (!('source' in cell)) errors.push(cp + ' missing source');
        if (!Array.isArray(cell.outputs)) errors.push(cp + ' missing outputs array');
        if (!('executionCount' in cell)) errors.push(cp + ' missing executionCount');
        if (!('metadata' in cell)) errors.push(cp + ' missing metadata');
        if (!('id' in cell)) errors.push(cp + ' missing id');
      });
    }
  }

  if (obj.type === 'lab') {
    if (!Array.isArray(obj.los)) errors.push(path + ' lab missing los array');
    if (!('pdf' in obj)) errors.push(path + ' lab missing pdf');
    if (!('pdfFile' in obj)) errors.push(path + ' lab missing pdfFile');
    if (obj.los) {
      obj.los.forEach((step, si) => {
        const sp = path + '/los[' + si + ']';
        if (!step.title) errors.push(sp + ' step missing title');
        if (!step.shortTitle) errors.push(sp + ' step missing shortTitle');
        if (!('contentMd' in step)) errors.push(sp + ' step missing contentMd');
        if (!('contentHtml' in step)) errors.push(sp + ' step missing contentHtml');
        if (!step.route) errors.push(sp + ' step missing route');
        if (!step.id) errors.push(sp + ' step missing id');
        if (step.type !== 'step') errors.push(sp + ' step type should be step');
      });
    }
  }
}

topics.forEach((t, i) => checkLO(t, 'topic[' + i + ']'));

if (errors.length === 0) {
  console.log('ALL STRUCTURAL CHECKS PASSED');
} else {
  console.log('ERRORS FOUND:');
  errors.forEach(e => console.log('  - ' + e));
}

// Count total content
let totalCells = 0, totalSteps = 0, totalSlides = 0;
function countContent(obj) {
  if (obj.type === 'notebook' && obj.cells) totalCells += obj.cells.length;
  if (obj.type === 'talk') totalSlides += obj.contentMd.split('---').filter(s => s.trim()).length;
  if (obj.type === 'lab' && obj.los) totalSteps += obj.los.length;
  if (obj.los) obj.los.forEach(countContent);
}
topics.forEach(countContent);
console.log('\nContent totals:');
console.log('  Notebook cells:', totalCells);
console.log('  Slide sections:', totalSlides);
console.log('  Lab steps:', totalSteps);
"
"}

